function pxParseSidFromBookUrl(bu) {
    try {
        var s = String(bu || '');
        var bm = s.match(/base64,([A-Za-z0-9+/=]+)/);
        if (!bm) return '';
        var b64 = bm[1];
        var decoded = '';
        try {
            var bytes = Packages.java.util.Base64.getDecoder().decode(b64);
            decoded = new Packages.java.lang.String(bytes, 'UTF-8');
        } catch (e1) {
            try {
                var bytes2 = Packages.java.util.Base64.getUrlDecoder().decode(b64);
                decoded = new Packages.java.lang.String(bytes2, 'UTF-8');
            } catch (e2) { return ''; }
        }
        if (!decoded) return '';
        var sm = decoded.match(/[?&]_px_sid=([^&]+)/);
        if (sm && sm[1]) {
            try { return decodeURIComponent(sm[1]); } catch (e) { return sm[1]; }
        }
        if (/novel\/series\/(\d+)/.test(decoded)) return decoded.match(/novel\/series\/(\d+)/)[1];
        if (/series_id=(\d+)/.test(decoded)) return decoded.match(/series_id=(\d+)/)[1];
        if (/[?&]id=\d+/.test(decoded)) return '🇨🇳';
    } catch (e) {}
    return '';
}

