	var saltStr = time + '28c1fdd170a5204386cb1313c7077b34f83e4aaf4aa829ce78c231e05b0bae2c';
	try { var jv = this.java || (typeof java !== 'undefined' ? java : null); if (jv && jv.md5Encode) return jv.md5Encode(saltStr); } catch(e) {}
	var md = Packages.java.security.MessageDigest.getInstance("MD5");
	md.update(new Packages.java.lang.String(saltStr).getBytes("UTF-8"));
	var dg = md.digest();
	var hx = '';
	for (var di = 0; di < dg.length; di++) { var bv = dg[di] & 0xFF; hx += (bv < 16 ? '0' : '') + bv.toString(16); }
	return hx;
}

