function checkOverAccess() {
    const {java, cache, source} = this;
    let lastCheck = cache.get('overAccessCheckTime');
    let now = Date.now();
    if (lastCheck && (now - lastCheck) < 4*60*60*1000) return;
    cache.put('overAccessCheckTime', now);
    try {
        let url = 'https://www.pixiv.net/rpc/index.php?mode=latest_message_threads2&num=5&lang=zh';
        let resp = java.ajax(gethd(url));
        if (!resp) return;
        let data = JSON.parse(resp);
        if (data.error) return;
        let threads = data.body.message_threads || [];
        let msg = threads.find(item => item.thread_name === 'pixiv事務局');
        if (msg && (now - msg.modified_at*1000) < 3*24*60*60*1000) {
            let time = new Date(msg.modified_at*1000);
            let timeStr = time.toLocaleString();
            java.longToast(`⚠️ 您于 ${timeStr} 触发 Pixiv 过度访问，请修改密码并重新登录。`);
        }
    } catch(e) {}
}

function pxOauth(postBody) {
	const {java} = this;
	let time = java.timeFormatUTC(Date.now(),"yyyy-MM-dd'T'HH:mm:ss'+00:00'",8*60*60*1000);
	let hash = timemd5(time);
	let req = 'POST /auth/token HTTP/1.1\r\nHost: oauth.secure.pixiv.net\r\n'+'User-Agent: '+ua+'\r\n'+'content-type: application/x-www-form-urlencoded\r\n'+'x-client-time: '+time+'\r\nx-client-hash: '+hash+'\r\n'+'accept-language: '+a_l+'\r\napp-os: Android\r\napp-os-version: Android 14\r\napp-version: '+appv+'\r\n'+'Content-Length: '+postBody.length+'\r\nConnection: close\r\n\r\n'+postBody;
	let sf = Packages.javax.net.ssl.SSLSocketFactory.getDefault();
	let ips = ['210.140.139.155','210.140.139.152','210.140.139.158','210.140.139.161'];
	let sock = null, lastErr = '';
	for (let i = 0; i < ips.length; i++) {
		try {
			let addr = Packages.java.net.InetAddress.getByName(ips[i]);
			sock = sf.createSocket(addr, 443);
			sock.setSoTimeout(12000);
			let os = sock.getOutputStream();
			os.write(new Packages.java.lang.String(req).getBytes('UTF-8'));
			os.flush();
			let rd = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(sock.getInputStream(),'UTF-8'));
			let sb = new Packages.java.lang.StringBuilder();
			let line;
			while ((line = rd.readLine()) != null) { sb.append(line); sb.append('\n'); }
			return String(sb.toString());
		} catch(e) { lastErr = e; try { if (sock != null) sock.close(); } catch(e2) {} }
	}
	throw lastErr == '' ? 'oauth直连失败：无可用IP' : lastErr;
}

